html, body { margin: 0; padding: 0; background: #000; overflow-x: hidden; font-family: sans-serif; }
.galaxy-wrap { position: relative; width: 100%; height: 400vh; }
#galaxy-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.galaxy-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.galaxy-msg {
  position: absolute; color: #fff; font-size: 22px; font-weight: bold; text-align: center;
  opacity: 0; transition: opacity 0.3s; text-shadow: 0 5px 15px rgba(0,0,0,0.8);
}

jsCode:
const mainWrap = document.getElementById('container');
mainWrap.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;position:relative;';

mainWrap.innerHTML = `
  <div class="galaxy-wrap">
    <canvas id="galaxy-canvas"></canvas>
    <div class="galaxy-text-layer">
      <div id="gMsg1" class="galaxy-msg" style="top:10%;">સ્ક્રોલ કરો ↓</div>
      <div id="gMsg2" class="galaxy-msg" style="font-size:35px; color:#00d2ff;">ગેલેક્સી બની રહી છે...</div>
      <div id="gMsg3" class="galaxy-msg" style="font-size:40px; color:#ff007f;">UNIVERSE</div>
    </div>
  </div>
`;

const cvs = document.getElementById('galaxy-canvas');
const ctx = cvs.getContext('2d');
let W, H;
let particles = [], targetShapes = [];
const pCount = 1000;

function getTxtPts(txt, size) {
  const tC = document.createElement('canvas');
  tC.width = W; tC.height = H;
  const tCtx = tC.getContext('2d');
  tCtx.fillStyle = 'white'; tCtx.font = `900 ${size}px sans-serif`;
  tCtx.textAlign = 'center'; tCtx.textBaseline = 'middle';
  tCtx.fillText(txt, W/2, H/2);
  const data = tCtx.getImageData(0,0,W,H).data;
  let pts = [];
  for(let y=0; y<H; y+=7){
    for(let x=0; x<W; x+=7){
      if(data[(y*W+x)*4+3] > 128) pts.push({x:x, y:y});
    }
  }
  return pts.length ? pts : [{x: W/2, y: H/2}];
}

function init() {
  W = cvs.width = mainWrap.clientWidth || window.innerWidth;
  H = cvs.height = mainWrap.clientHeight || window.innerHeight;

  let s1 = []; // સર્પિલ ગેલેક્સી (Spiral Galaxy)
  for(let i=0; i<pCount; i++) {
    let angle = i * 0.1; let r = angle * 1.5;
    s1.push({x: W/2 + Math.cos(angle)*r, y: H/2 + Math.sin(angle)*r});
  }

  let s2 = []; // વિસ્ફોટ (Explosion)
  for(let i=0; i<pCount; i++) s2.push({ x: Math.random()*W, y: Math.random()*H });

  let s3 = getTxtPts('COSMIC', Math.min(W/4, 60));
  let s4 = getTxtPts('ZYNK', Math.min(W/3, 80));

  targetShapes = [s1, s2, s3, s4, s4];
  particles = [];
  for(let i=0; i<pCount; i++){
    particles.push({ x: W/2, y: H/2, c: `hsl(${200 + Math.random()*60}, 100%, 60%)` }); 
  }
}
init(); window.addEventListener('resize', init);

let sProg = 0;
mainWrap.addEventListener('scroll', () => {
  sProg = mainWrap.scrollTop / (mainWrap.scrollHeight - mainWrap.clientHeight);
  document.getElementById('gMsg1').style.opacity = (sProg < 0.1) ? 1 : 0;
  document.getElementById('gMsg2').style.opacity = (sProg > 0.3 && sProg < 0.5) ? 1 : 0;
  document.getElementById('gMsg3').style.opacity = (sProg > 0.8) ? 1 : 0;
});

function lerp(a, b, t) { return a + (b - a) * t; }

function anim() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.2)'; 
  ctx.fillRect(0,0,W,H);

  let stage = sProg * 4;
  let cStage = Math.floor(stage);
  let nStage = Math.min(cStage + 1, 4);
  let tProg = stage - cStage;

  let pts1 = targetShapes[cStage], pts2 = targetShapes[nStage];

  for(let i=0; i<pCount; i++){
    let p = particles[i];
    let t1 = pts1[i % pts1.length], t2 = pts2[i % pts2.length];
    let tx = lerp(t1.x, t2.x, tProg), ty = lerp(t1.y, t2.y, tProg);

    // ગેલેક્સીને ગોળ ફેરવવા માટે
    if(cStage === 0) { 
        let angle = Date.now()*0.001 + i*0.1;
        let r = i*0.1;
        tx = W/2 + Math.cos(angle)*r; ty = H/2 + Math.sin(angle)*r;
    }

    p.x += (tx - p.x) * 0.08; p.y += (ty - p.y) * 0.08;
    ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI*2);
    ctx.fillStyle = p.c; ctx.fill();
  }
  requestAnimationFrame(anim);
}
anim();
